'use strict';
const BirthEras=(()=>{
 const eras=BIRTH_ERAS,years=eras.map(e=>e.year),current=y=>eras.filter(e=>e.year<=y).at(-1)||eras[0];
 function picker(selected){return `<fieldset class="era-picker"><legend>อยากเกิดในยุคไหน?</legend><p>ปี 1000 คือยุคปัจจุบัน · ปี 1500 คือการเริ่มชีวิตในอนาคต</p><select id="birthYear" aria-label="เลือกปีเกิด">${eras.map(e=>`<option value="${e.year}" ${selected===e.year?'selected':''}>ปี ${e.year} · ${e.name}</option>`).join('')}</select><div class="era-preview" aria-live="polite">${preview(selected)}</div></fieldset>`;}
 function preview(y){const e=current(y);return `<h3>ปี ${e.year} · ${e.name}</h3><p>${e.intro}</p><dl><dt>เติบโตและเรียนรู้</dt><dd>${e.learning}</dd><dt>งานและการหาเลี้ยงชีพ</dt><dd>${e.work}</dd><dt>สิ่งที่อาจต้องรับมือ</dt><dd>${e.tension}</dd><dt>หากเกิดเป็นสิ่งมีชีวิตนอกเมือง</dt><dd>${e.native}</dd></dl>`;}
 const events=[];
 function add(e,part,min,max,title,text,choices,native=false){const id='era37-'+e.year+'-'+part;const row={id,title,text,min,max,eraOnly:e.year,eraNative:native,realmNative:native,humanOnly:!native,certain:true,once:true,lifeOpportunity:true,choices:choices.map(([label,hint,effect,success])=>({label,hint,effect,success}))};events.push(row);EVENTS.push(row);}
 const conflicts=[
 ['บ่อที่คนทั้งหมู่บ้านใช้','ผนังบ่อเริ่มทรุด คนข้างบ้านขอให้ช่วยซ่อมก่อนฝนมา แต่ทุกบ้านต่างต้องเก็บแรงไว้หาอาหาร','ช่วยออกค่าหินและเชือก','ลงแรงขนหินกับคนข้างบ้าน','เก็บแรงไว้ดูแลบ้านของตน',900],
 ['คนค้ำชื่อให้คาราวาน','เพื่อนที่ค้าขายด้วยกันขอให้คุณรับรองสินค้าล็อตใหม่ คุณยังไม่เคยเห็นของทั้งหมด ถ้ามีปัญหา คนซื้อจะกลับมาหาคุณด้วย','จ้างคนตรวจของก่อนรับรอง','ตรวจบัญชีและขอดูของด้วยตนเอง','ไม่รับรองของที่ยังตรวจไม่ครบ',1400],
 ['เสบียงที่ด่านขอเพิ่ม','ข่าวจากชายแดนมาถึงพร้อมคำขอเสบียง เจ้าหน้าที่ขอให้แต่ละบ้านช่วย แต่ของที่ส่งไปคือส่วนที่คุณอาจต้องใช้เอง','ซื้อเสบียงส่งไปพร้อมใบรับ','ช่วยตรวจรายชื่อและจัดของที่มี','กันส่วนของครอบครัวไว้ก่อน',1200],
 ['ค่าเรียนที่ไม่อยู่ในงบ','คุณพบหลักสูตรที่ต่อยอดงานได้ แต่ค่าเรียนยังไม่รวมหนังสือและค่าเดินทาง ถ้าเรียนตอนค่ำก็จะมีเวลาพักน้อยลง','ลงเรียนและซื้ออุปกรณ์ให้ครบ','ขอใช้ตำราส่วนกลางและฝึกหลังเลิกงาน','เลื่อนไปก่อนจนมีเงินสำรอง',2400]
 ];
 for(let i=0;i<eras.length;i++){const e=eras[i],a=conflicts[i];add(e,'adult',18,80,a[0],a[1],[[a[2],`เงิน −${a[5]} · สายสัมพันธ์ +6 · ปัญญา +4`,{gold:-a[5],bond:6,wisdom:4},'คุณกันเงินส่วนตัวให้เรื่องนี้ แล้วกลับมาจัดงบที่เหลือใหม่'],[a[3],'ปัญญา +5 · สุขภาพ −3',{wisdom:5,health:-3},'งานเดินต่อได้โดยไม่ต้องจ่ายเพิ่ม แต่เวลาพักของคุณหายไปหลายเย็น'],[a[4],'ความสุข +3 · สายสัมพันธ์ −2',{joy:3,bond:-2},'คุณบอกเหตุผลตรง ๆ บางคนเข้าใจ บางคนยังผิดหวัง แต่บ้านของคุณก็มีภาระที่ต้องดูแล']]);
 add(e,'child',7,12,i===0?'ครูที่อยู่ข้างบ้าน':i===3?'หนังสือที่ยืมกลับมาได้':'บทเรียนหลังมื้อเช้า',i===0?'ผู้เฒ่าเอาถ่านมาขีดตัวเลขบนไม้ คุณลองนับถุงเมล็ดที่บ้านเก็บไว้ ก่อนถามว่าชื่อของตัวเองเขียนอย่างไร':i===3?'ครูให้ยืมหนังสือกลับบ้าน คุณอยากอ่านให้จบ แต่ยังมีงานเล็ก ๆ ที่รับปากคนในบ้านไว้':'คนในบ้านพาไปพบผู้สอน คุณยังไม่รู้ว่าจะชอบเรียนอะไร จึงขอลองทีละอย่าง',[[i===0?'ลองอ่านและนับของในบ้าน':'ฝึกอ่านกับผู้สอน','ปัญญา +5',{wisdom:5},'คุณสะกดคำได้ช้า ๆ คนที่นั่งข้างกันรอจนคุณอ่านจบ'],['ขอฝึกสิ่งที่ใช้มือทำ','พลัง +4 · ความสุข +2',{power:4,joy:2},'คุณเริ่มจากงานชิ้นเล็ก มีคนคอยช่วยเมื่อมือยังไม่คล่อง'],['ลองไปพร้อมเพื่อน','สายสัมพันธ์ +5',{bond:5},'เพื่อนจำสิ่งที่คุณลืมได้ คุณก็ช่วยเขาในส่วนที่ยังทำไม่ถนัด']]);
 add(e,'native',18,100,'ทางผ่านที่เปลี่ยนไป',e.native,[['ยอมแบ่งทางและเฝ้าดูอีกฝ่าย','สายสัมพันธ์ +5 · แหล่งดำรงชีวิต −5',{bond:5,driveResource:-5},'คุณถอยแนวพักไปเล็กน้อย อีกฝ่ายเริ่มจำได้ว่าพื้นที่ส่วนไหนยังเป็นของคุณ'],['ใช้กำลังและทรัพยากรป้องกันถิ่น','พลัง +5 · แหล่งดำรงชีวิต −10',{power:5,driveResource:-10},'คุณรักษาพื้นที่ไว้ได้ แต่ต้องใช้แหล่งสำรองมากกว่าที่เคย'],['อ้อมไปหาทางใช้ชีวิตที่เงียบกว่า','สุขภาพ −3 · ความสุข +3',{health:-3,joy:3},'การหาพื้นที่ใหม่ทำให้เหนื่อย คุณค่อย ๆ สำรวจจนเจอที่พักซึ่งยังไม่มีใครรบกวน']],true);}
 function matches(s,e){if(!e.eraOnly)return true;if(current(WorldTimeline.year(s)).year!==e.eraOnly)return false;return e.eraNative?Ecology.native(s):s.race===0;}
 function next(s){const last=s.diary?.entries.find(e=>e.key?.startsWith('decision-era37-'));if(last&&Engine.biological(s)-Engine.ageEquivalent(last.age,s.race)<2)return null;return events.find(e=>Engine.eligible(s,e))||null;}
 function careerReason(s,index){const name=JOBS[index]?.[0]||'',y=WorldTimeline.year(s);if(y<1200&&/รถไฟรูน|กังหันเมฆ/.test(name))return 'งานนี้ยังไม่เกิดขึ้นในยุคนี้';if(y<800&&/ครูโรงเรียนชุมชน/.test(name))return 'ยุคนี้ยังเรียนกับคนในชุมชนและผู้รู้เป็นหลัก';return '';}
 function learningLabel(s,key){if(s.race!==0)return null;const y=WorldTimeline.year(s);if(key==='community'&&y<800)return 'เรียนกับคนในหมู่บ้าน';if(key==='academy'&&y<800)return 'ฝากตัวเรียนกับผู้รู้';return null;}
 function growth(s,entry){if(s.race!==0||entry?.key!=='growth-6')return entry;const early=WorldTimeline.year(s)<800,elite=DynastyLife.elite(s);return {...entry,title:elite?'ครูมาสอนที่เรือน':early?'เริ่มเรียนกับคนใกล้บ้าน':'วันแรกที่ได้พบผู้สอน',paragraphs:[elite?'ผู้ดูแลจัดโต๊ะและสมุดไว้ให้ ครูขอให้คุณลองเขียนชื่อของตัวเองก่อนเริ่มบทเรียน':early?'คนในบ้านชวนคุณนั่งข้าง ๆ แล้วขีดตัวอักษรลงบนไม้ คุณลองเขียนตาม ตัวแรกยังเบี้ยวอยู่มาก':'คุณเตรียมของใช้ไปพบผู้สอน ได้ลองอ่านและทำงานเล็ก ๆ พร้อมเด็กคนอื่น บางคนรู้จักกันอยู่แล้ว บางคนเพิ่งได้คุยกันวันนี้']};}
 return {eras,years,current,picker,preview,events,matches,next,careerReason,learningLabel,growth};
})();
